import { data, takaro } from '@takaro/helpers';
async function main() {
    const { gameServerId, module: mod } = data;
    const AFK_MINUTES = data.module.userConfig.MinutesAfkBeforeKick || 10;

    // Get API response searching for players in the specified game server with online value of true.
    const playersRes = await takaro.playerOnGameserver.playerOnGameServerControllerSearch({
        filters: {
            gameServerId: [gameServerId],
            online: [true],
        },
    });

    // api.takaro.io/api.html for Player on Game Server Search documentation indicates by the response schema. 
    // Data is an array of Data objects.
    const players = playersRes.data.data || [];

    if (players.length === 0) {
        return;
    }

    const now = Date.now();

    // Loop through online players (oP) in list of players.
    // javascript uses 'of' not 'in'
    for (const oP of players) {
        // Get all data we want to use for afk/idle checks
        const playerId = oP.playerId;
        // position data
        const x = oP.positionX;
        const y = oP.positionY;
        const z = oP.positionZ;

        // player inventory
        const inv = oP.inventory;
        let processPos = true;
        let processInv = true;
        if ((x === undefined || y === undefined || z === undefined) && inv === undefined) {
            // We need one of these pieces of data
            // Either position, last seen, or inventory
            continue;
        }
        if (x === undefined || y === undefined || z === undefined) {
            processPos = false;
        }
        if (inv === undefined) {
            processInv = false;
        }

        let name = 'Unknown';

        try {
            const playerRes = await takaro.player.playerControllerGetOne(playerId);
            name = playerRes.data.data.name || 'Unknown';
        } catch (ex) {

        }

        const posKey = `pos_${playerId}`;
        const invKey = `inv_${playerId}`;

        // Get existing position data for player from takaro data
        const existingPos = await takaro.variable.variableControllerSearch({
            filters: {
                key: [posKey],
                gameServerId: [gameServerId],
                moduleId: [mod.moduleId],
            },
        });

        // Get existing inventory data for player from takaro data
        const existingInv = await takaro.variable.variableControllerSearch({
            filters: {
                key: [invKey],
                gameServerId: [gameServerId],
                moduleId: [mod.moduleId],
            },
        });

        let lastPos = null;
        let lastInv = null;

        // parse existing player position data from takaro into variable
        if (existingPos.data.data && existingPos.data.data.length > 0) {
            try {
                lastPos = JSON.parse(existingPos.data.data[0].value);
            } catch (ex) {
                lastPos = null;
            }
        }
        // parse existing player inventory data from takaro into variable
        if (existingInv.data.data && existingInv.data.data.length > 0) {
            try {
                lastInv = JSON.parse(existingInv.data.data[0].value);
            } catch (ex) {
                lastInv = null;
            }
        }

        let moved = null;
        let inventoryChange = null;
        let timeToCheck = null;

        if (processPos) {
            // Create new variable to store the player position data in takaro for checking against on later runs.
            if (!lastPos) {
                await takaro.variable.variableControllerCreate({
                    key: posKey,
                    value: JSON.stringify({ x: x, y: y, z: z, timestamp: now }),
                    gameServerId: gameServerId,
                    moduleId: mod.moduleId,
                });
            } else {
                moved = lastPos.x !== x || lastPos.y !== y || lastPos.z !== z;
                if (timeToCheck !== null) {
                    if (lastPos.timestamp > timeToCheck) {
                        timeToCheck = lastPos.timestamp;
                    }
                } else {
                    timeToCheck = lastPos.timestamp;
                }
            }

            if (moved) {
                await takaro.variable.variableControllerUpdate(existingPos.data.data[0].id, {
                    value: JSON.stringify({ x: x, y: y, z: z, timestamp: now }),
                });
            }
        }

        if (processInv) {
            // Create new variable to store the player inventory data in takaro for checking against on later runs.
            if (!lastInv) {
                await takaro.variable.variableControllerCreate({
                    key: invKey,
                    value: JSON.stringify({ inventory: inv, timestamp: now }),
                    gameServerId: gameServerId,
                    moduleId: mod.moduleId,
                });

            } else {
                inventoryChange = JSON.stringify(lastInv.inventory) !== JSON.stringify(inv);
                if (timeToCheck !== null) {
                    if (lastInv.timestamp > timeToCheck) {
                        timeToCheck = lastInv.timestamp;
                    }
                } else {
                    timeToCheck = lastInv.timestamp;
                }
            }

            if (inventoryChange) {
                await takaro.variable.variableControllerUpdate(existingInv.data.data[0].id, {
                    value: JSON.stringify({ inventory: inv, timestamp: now }),
                });
            }
        }


        if (moved === true || inventoryChange === true) {
            continue;
        } else if (timeToCheck) {
            const idleMinutes = (now - timeToCheck) / 1000 / 60;
            if (idleMinutes >= AFK_MINUTES) {
                await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
                    command: `kick ${name} "You have been disconnected by AFK protection. The server is set to disconnect players after being idle for ${AFK_MINUTES} minutes."`,
                });

                await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
                    message: `${name} was disconnected by AFK protection.`
                });
            }
        }
    }
}
await main();
